/** SwiftUI `Transaction`. */
export type Transaction = SwiftUI.Transaction;

/** Starts a SwiftUI `Transaction`. Each call returns a new value, as `compose()` does. */
export const createTransaction = (
  value?: SwiftUI.Transaction
): SwiftUI.TransactionChain =>
  valueChain<SwiftUI.TransactionChain>(
    value ?? {},
    ['addAnimationCompletion'],
    [],
    {
      type: 'Transaction',
      members: {
        animation: { kind: 'property', returns: 'Animation?' },
        disablesAnimations: { kind: 'property', returns: 'Bool' },
        isContinuous: { kind: 'property', returns: 'Bool' },
        scrollPositionUpdatePreservesVelocity: {
          kind: 'property',
          returns: 'Bool',
        },
        scrollTargetAnchor: { kind: 'property', returns: 'UnitPoint?' },
        tracksVelocity: { kind: 'property', returns: 'Bool' },
      },
    }
  );

